do $$declare x jsonb;f uuid;member uuid;page jsonb;work jsonb;p jsonb;r uuid:=gen_random_uuid();saved jsonb;again jsonb;before_job jsonb;begin
 select t.x into x from late_test.context t;f:=(x->>'factory')::uuid;
 perform set_config('request.jwt.claim.sub',x->>'owner',false);perform set_config('request.jwt.claim.role','authenticated',false);
 select id into member from public.memberships where factory_id=f and user_id=(x->>'owner')::uuid;
 page:=public.production_shift_work(f);work:=page#>'{rows,0}';
 p:=jsonb_build_object('unit_kind','line','production_unit',x->>'line','item',x->>'item','technician',member,'good',2,'discarded_quantity',0,'scrap_kg',.25,
 'recording_context',jsonb_build_object('version',3,'execution_key',work->>'execution_key','occurrence_key',page#>>'{occurrence,occurrence_key}','context_hash',work->>'context_hash','current_shift_quantity_confirmed',false));
 saved:=public.record_lean_production(f,p,r);
 perform late_test.ok(saved->>'outcome'='COMMITTED','active COMMITTED');
 perform late_test.ok((select original_period_end=created_at and effective_period_end=created_at from public.production_entries where id=(saved->>'id')::uuid),'active period ends at saved server recording instant');
 again:=public.record_lean_production(f,p,r);
 perform late_test.ok((again-'replayed')=(saved-'replayed') and again->>'replayed'='true','immutable exact replay');
 perform late_test.ok((select on_hand=2 from public.finished_goods_balances where factory_id=f),'one Good stock credit');
 perform late_test.ok((select origin_occurrence_key=page#>>'{occurrence,occurrence_key}' and quantity_identified=0 from public.finished_goods_sources where factory_id=f),'frozen source origin without physical identification');
 perform public.finish_product_item(f,(x->>'item')::uuid);
 page:=public.production_shift_work(f);work:=page#>'{rows,0}';
 p:=jsonb_set(p,'{recording_context,context_hash}',work->'context_hash');
 before_job:=(select to_jsonb(o) from public.production_orders o where id=(x->>'item')::uuid);
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p,gen_random_uuid()),'recording_disabled');
 update private.production_recording_v3_activation set enabled=true,schema_contract_version=3 where factory_id=f;
 saved:=public.record_lean_production(f,p,gen_random_uuid());
 perform late_test.ok(saved->>'recording_kind'='LATE_ORDINARY','late accepted in isolated gate test');
 perform late_test.ok((select actual_start=(before_job->>'actual_start')::timestamptz and actual_finish=(before_job->>'actual_finish')::timestamptz and status='completed' from public.production_orders where id=(x->>'item')::uuid),'completed execution unchanged');
 perform late_test.ok((select on_hand=4 from public.finished_goods_balances where factory_id=f),'late Good credited once');
 update private.production_recording_v3_activation set enabled=false,schema_contract_version=0 where factory_id=f;
end$$;
select count(*) as assertions from late_test.checks;
do $$declare x jsonb;foreign_x jsonb;f uuid;p jsonb;r uuid:=gen_random_uuid();receipt jsonb;current jsonb;e uuid;source uuid;cp jsonb;before_stock numeric;uid uuid;pkg uuid;viewer_retry uuid:=gen_random_uuid();begin
 select t.x into x from late_test.context t;f:=(x->>'factory')::uuid;
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform late_test.ok((select not enabled and schema_contract_version=0 from private.production_recording_v3_activation where factory_id=f),'gate left disabled after local smoke');
 perform late_test.ok(not has_table_privilege('authenticated','private.production_recording_v3_activation','SELECT'),'private gate hidden');
 perform late_test.ok(not has_function_privilege('authenticated','private.recording_v3_context(uuid,uuid,jsonb)','EXECUTE'),'private admission helper revoked');
 perform late_test.ok(not has_function_privilege('authenticated','private.record_production(uuid,text,uuid,uuid,uuid,numeric,numeric,text,boolean,uuid,uuid,text,numeric,text,uuid,numeric,jsonb,jsonb)','EXECUTE'),'new quantity worker overload revoked');
 perform late_test.ok(not has_function_privilege('anon','public.production_recording_request_status(uuid,uuid)','EXECUTE'),'status anon grant revoked');
 perform late_test.ok((public.production_recording_request_status(f,r)->>'outcome')='UNKNOWN','absent request honestly UNKNOWN');
 p:=late_test.payload(x,3);
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p,gen_random_uuid()),'recording_disabled');
 update private.production_recording_v3_activation set enabled=true,schema_contract_version=0 where factory_id=f;
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p,gen_random_uuid()),'recording_disabled');
 delete from private.production_recording_v3_activation where factory_id=f;
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p,gen_random_uuid()),'recording_disabled');
 insert into private.production_recording_v3_activation(factory_id,enabled,schema_contract_version) values(f,true,3);
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,jsonb_set(p,'{recording_context,execution_key}',to_jsonb(repeat('0',64))),gen_random_uuid()),'recording_stale_context');
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p||'{"recording_kind":"LATE_ORDINARY"}',gen_random_uuid()),'recording_invalid_payload');
 receipt:=public.record_lean_production(f,p,r);e:=(receipt->>'entry_id')::uuid;
 perform late_test.ok((public.production_recording_request_status(f,r)->>'outcome')='COMMITTED','committed status');
 perform late_test.ok(public.record_lean_production(f,p||'{"startup_kg":0.00,"unfinished":0.0,"notes":"","input_quantity":0}',r)-'replayed'=receipt-'replayed','canonical optional defaults and numeric equivalents');
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p||'{"good":4}',r),'request_conflict');
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p||'{"notes":"different"}',r),'request_conflict');
 perform late_test.fails(format('update public.production_entries set request_payload=%L where id=%L','{}',e),'recording_origin_immutable');
 perform late_test.fails(format('update public.production_entries set accepted_at=clock_timestamp() where id=%L',e),'recording_receipt_immutable');
 perform late_test.fails(format('update public.finished_goods_sources set shift_name=%L where entry_id=%L','invented',e),'recording_source_immutable');
 -- Source-backed decrease uses the existing stock selector; origin and receipt survive.
 cp:=jsonb_build_object('entry',e,'good',2,'discarded_quantity',0,'scrap_kg',0,'startup_kg',0,'reason','M2 source correction','unfinished',0,'remaining_work','');
 perform public.source_stock_command(f,'correct',cp,jsonb_build_array(jsonb_build_object('source_id',null,'quantity','1')),gen_random_uuid());
 current:=public.production_recording_request_status(f,r);
 perform late_test.ok(current->'receipt'=receipt and current#>>'{current,good}'='2','status separates immutable receipt from correction');
 perform late_test.ok((select previous_occurrence_key=corrected_occurrence_key and not attribution_changed from public.production_entry_corrections where entry_id=e),'quantity correction retains dated attribution audit');
 perform late_test.ok((select origin_occurrence_key=receipt->>'occurrence_key' and quantity_credited=2 from public.finished_goods_sources where entry_id=e),'correction retains frozen source and adjusts credit once');
 cp:=cp||jsonb_build_object('change_shift',true,'shift',x->>'shift');
 perform late_test.fails(format('select public.correct_lean_production(%L,%L,%L)',f,cp,gen_random_uuid()),'recording_dated_correction_required');
 cp:=cp||jsonb_build_object('corrected_occurrence_key',receipt->>'occurrence_key');
 perform public.correct_lean_production(f,cp,gen_random_uuid());
 perform late_test.ok((select original_occurrence_key=receipt->>'occurrence_key' from public.production_entries where id=e),'explicit dated correction retains immutable origin');
 -- New late output can create WIP, but cannot consume an existing lot via late mode.
 p:=late_test.payload(x,1)||jsonb_build_object('unfinished',2,'remaining_work','Finish cooling');
 receipt:=public.record_lean_production(f,p,gen_random_uuid());
 perform late_test.ok((select quantity_available=2 from public.unfinished_lots where source_entry_id=(receipt->>'id')::uuid),'late new WIP lot created once');
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p||jsonb_build_object('input_lot',gen_random_uuid(),'input_quantity',3),gen_random_uuid()),'recording_invalid_context');
 -- Current configured names may change; frozen source names remain the original occurrence.
 perform public.configure_production_shift(f,'Renamed after completion','اسم لاحق',(select start_time from public.production_shifts where id=(x->>'shift')::uuid),(select end_time from public.production_shifts where id=(x->>'shift')::uuid),(x->>'shift')::uuid,true);
 p:=late_test.payload(x,1);receipt:=public.record_lean_production(f,p,gen_random_uuid());
 perform late_test.ok((select s.shift_name='M2 current' and s.factory_timezone='UTC' from public.finished_goods_sources s where entry_id=(receipt->>'id')::uuid),'archived renamed shift uses frozen source labels');
 -- Existing authority, not role titles: viewer denial, package grant, revocation and cross-factory.
 select on_hand into before_stock from public.finished_goods_balances where factory_id=f;
 perform set_config('request.jwt.claim.sub',x->>'viewer',false);
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p,gen_random_uuid()),'42501');
 perform late_test.fails(format('select public.production_recording_request_status(%L,%L)',f,r),'42501');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 select id into pkg from public.permission_packages where factory_id=f and template_key='planning_engineer';
 perform public.set_member_permission_packages(f,(x->>'viewer')::uuid,array[pkg],array[]::uuid[]);
 perform set_config('request.jwt.claim.sub',x->>'viewer',false);
 perform late_test.ok(public.production_recording_request_status(f,r)->>'outcome'='UNKNOWN','same-factory different actor cannot discover receipt');
 p:=late_test.payload(x,1);receipt:=public.record_lean_production(f,p,viewer_retry);
 perform late_test.ok(receipt->>'outcome'='COMMITTED','package-only editor can commit with approved technician');
 select on_hand into before_stock from public.finished_goods_balances where factory_id=f;
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p,viewer_retry),'request_conflict');
 perform public.set_member_permission_packages(f,(x->>'viewer')::uuid,array[]::uuid[],array[pkg]);
 perform set_config('request.jwt.claim.sub',x->>'viewer',false);
 perform late_test.fails(format('select public.production_recording_request_status(%L,%L)',f,r),'42501');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform late_test.ok((select on_hand=before_stock from public.finished_goods_balances where factory_id=f),'denied requests do not change stock');
 foreign_x:=mp_test.fixture('m2-foreign');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform late_test.fails(format('select public.production_recording_request_status(%L,%L)',foreign_x->>'factory',r),'42501');
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',foreign_x->>'factory',p,gen_random_uuid()),'42501');
 update private.production_recording_v3_activation set enabled=false where factory_id=f;
 perform late_test.ok(public.record_lean_production(f,(select request_payload->'payload' from public.production_entries where factory_id=f and request_id=r),r)->>'replayed'='true','committed replay after disable');
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p-'recording_context',gen_random_uuid()),'recording_invalid_unit');
end$$;
select count(*) as total_assertions from late_test.checks;
